	/** How many tasks the content defines. */
	public static int count() {
		int n = 0;
		for (int i = 0; i < NAME.length; i++) {
			if (NAME[i].length() > 0) {
				n++;
			}
		}
		return n;
	}

	/** What a task id is called, or "" for one this table does not know. */
	public static String name(int target) {
		return target < 0 || target >= NAME.length ? "" : NAME[target];
	}
